{"exit_code": 0, "stdout": "#!/usr/bin/env python3
"""elt-load, the extract + load tool inside the sandbox.

the agent describes what to copy in a yaml file and this does the copying, like a tiny airbyte.
where to write comes from the environment (ELT_WAREHOUSE_URL + ELT_WAREHOUSE_SCHEMA) so the
grader can rerun the same file into a fresh warehouse

    elt-load /workspace/elt/load.yaml

    sources:
      pg:    {type: postgres, host: ..., port: 5432, database: ..., user: ..., password: ...}
      mongo: {type: mongodb, connection_string: ..., database: ...}
      s3:    {type: s3, endpoint_url: ..., access_key_id: ..., secret_access_key: ..., region: ...}
      api:   {type: api, base_url: http://elt-api:5005}
      web:   {type: file}
    streams:
      - {source: pg, table: address}                      # schema defaults to public
      - {source: mongo, collection: author}
      - {source: s3, path: s3://bucket/country.csv}        # format from the extension
      - {source: api, path: /books/publisher}
      - {source: web, url: http://..., format: jsonl, name: address_status}

each stream lands in a table called `name`, or the table/collection/file name if not given.
tables are replaced on every run
"""

import csv
import io
import json
import os
import sys
import time
from pathlib import PurePosixPath
from urllib.parse import urlparse

import pandas as pd
import requests
import yaml
from sqlalchemy import create_engine

FORMATS = ("csv", "jsonl", "json", "parquet")


def read_bytes(raw: bytes, fmt: str) -> pd.DataFrame:
    if fmt == "csv":
        return pd.read_csv(io.BytesIO(raw))
    if fmt == "jsonl":
        return pd.read_json(io.BytesIO(raw), lines=True)
    if fmt == "json":
        return pd.DataFrame(json.loads(raw))
    if fmt == "parquet":
        return pd.read_parquet(io.BytesIO(raw))
    raise ValueError(f"format must be one of {FORMATS}, got {fmt!r}")


def guess_format(path: str, stream: dict) -> str:
    fmt = stream.get("format") or PurePosixPath(urlparse(path).path).suffix.lstrip(".")
    if fmt not in FORMATS:
        raise ValueError(f"can't tell the format of {path!r}, set format: to one of {FORMATS}")
    return fmt


def default_name(stream: dict) -> str:
    for key in ("table", "collection", "path", "url"):
        if stream.get(key):
            return PurePosixPath(urlparse(str(stream[key])).path).stem.split(".")[-1]
    raise ValueError("stream needs a name")


def extract_postgres(src: dict, stream: dict) -> pd.DataFrame:
    url = (
        f"postgresql+psycopg2://{src['user']}:{src['password']}"
        f"@{src['host']}:{src.get('port', 5432)}/{src['database']}"
    )
    schema = stream.get("schema") or src.get("schema") or "public"
    engine = create_engine(url)
    try:
        with engine.connect() as c:
            return pd.read_sql_table(stream["table"], c, schema=schema)
    finally:
        engine.dispose()


def extract_mongodb(src: dict, stream: dict) -> pd.DataFrame:
    from pymongo import MongoClient

    client = MongoClient(src["connection_string"], serverSelectionTimeoutMS=10_000)
    try:
        docs = list(client[src["database"]][stream["collection"]].find())
    finally:
        client.close()
    df = pd.DataFrame(docs)
    if "_id" in df:
        df["_id"] = df["_id"].astype(str)
    # nested stuff goes in as json text, cast it in sql if needed
    for col in df.columns:
        if df[col].map(lambda v: isinstance(v, dict | list)).any():
            df[col] = df[col].map(
                lambda v: json.dumps(v, default=str) if isinstance(v, dict | list) else v
            )
    return df


def extract_s3(src: dict, stream: dict) -> pd.DataFrame:
    import boto3

    parsed = urlparse(stream["path"])
    if parsed.scheme != "s3":
        raise ValueError(f"s3 path must look like s3://bucket/key, got {stream['path']!r}")
    client = boto3.client(
        "s3",
        endpoint_url=src.get("endpoint_url"),
        aws_access_key_id=src.get("access_key_id"),
        aws_secret_access_key=src.get("secret_access_key"),
        region_name=src.get("region", "us-east-1"),
    )
    obj = client.get_object(Bucket=parsed.netloc, Key=parsed.path.lstrip("/"))
    return read_bytes(obj["Body"].read(), guess_format(stream["path"], stream))


def extract_api(src: dict, stream: dict) -> pd.DataFrame:
    url = src["base_url"].rstrip("/") + "/" + stream["path"].lstrip("/")
    resp = requests.get(url, timeout=120)
    resp.raise_for_status()
    return pd.DataFrame(resp.json())


def extract_file(src: dict, stream: dict) -> pd.DataFrame:
    url = stream["url"]
    if urlparse(url).scheme not in ("http", "https"):
        raise ValueError(f"file url must be http(s), got {url!r}")
    resp = requests.get(url, timeout=120)
    resp.raise_for_status()
    return read_bytes(resp.content, guess_format(url, stream))


EXTRACTORS = {
    "postgres": extract_postgres,
    "mongodb": extract_mongodb,
    "s3": extract_s3,
    "api": extract_api,
    "file": extract_file,
}


def copy_into_postgres(table, conn, keys, data_iter):
    # pandas recipe, COPY is way faster than row by row inserts
    buf = io.StringIO()
    csv.writer(buf).writerows(data_iter)
    buf.seek(0)
    cols = ", ".join('"' + k.replace('"', '""') + '"' for k in keys)
    name = '"' + table.name.replace('"', '""') + '"'
    if table.schema:
        name = '"' + table.schema.replace('"', '""') + '".' + name
    with conn.connection.cursor() as cur:
        cur.copy_expert(f"COPY {name} ({cols}) FROM STDIN WITH CSV", buf)


def load(df: pd.DataFrame, name: str, engine, schema: str) -> None:
    method = copy_into_postgres if engine.dialect.name == "postgresql" else "multi"
    df.to_sql(name, engine, schema=schema, if_exists="replace", index=False, method=method)


def lookup_source(sources: dict, stream: dict) -> dict:
    # spell out what went wrong, a bare KeyError doesn't help anyone fix their yaml
    name = stream.get("source")
    if name not in sources:
        raise ValueError(f"source {name!r} isn't defined, the sources section has {list(sources)}")
    src = sources[name]
    if src.get("type") not in EXTRACTORS:
        raise ValueError(
            f"source {name!r} has type {src.get('type')!r}, must be one of {list(EXTRACTORS)}"
        )
    return src


def main(argv: list[str]) -> int:
    if len(argv) == 2 and argv[1] in ("-h", "--help"):
        print(__doc__)
        return 0
    if len(argv) != 2:
        print("usage: elt-load <load.yaml>   (elt-load --help for the format)", file=sys.stderr)
        return 2
    try:
        with open(argv[1]) as f:
            spec = yaml.safe_load(f)
        sources, streams = spec["sources"], spec["streams"]
    except Exception as e:  # noqa: BLE001
        print(f"bad config: {e!r}", file=sys.stderr)
        return 2

    engine = create_engine(os.environ["ELT_WAREHOUSE_URL"])
    schema = os.environ["ELT_WAREHOUSE_SCHEMA"]
    failed = 0
    for stream in streams:
        start = time.time()
        try:
            name = stream.get("name") or default_name(stream)
            src = lookup_source(sources, stream)
            df = EXTRACTORS[src["type"]](src, stream)
            load(df, name, engine, schema)
            print(f"ok    {name}: {len(df)} rows ({time.time() - start:.1f}s)")
        except Exception as e:  # noqa: BLE001
            failed += 1
            print(f"FAIL  {stream}: {type(e).__name__}: {e}"[:2000], file=sys.stderr)
    engine.dispose()
    print(f"{len(streams) - failed}/{len(streams)} streams loaded")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
